local GrainAugerMaker = {}
local PRODUCTS = {
    iron_grainauger = { name = "Železni spiralni transporter za žito", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni spiralni transporter za žito za mlinarje." },
    bronze_grainauger = { name = "Bronast spiralni transporter za žito", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast spiralni transporter za žito za mlinarje." },
    silver_grainauger = { name = "Srebrn spiralni transporter za žito", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn spiralni transporter za žito za mlinarje." },
    gilded_grainauger = { name = "Pozlačen spiralni transporter za žito", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen spiralni transporter za žito za mlinarje." },
    jewel_set_grainauger = { name = "Draguljast spiralni transporter za žito", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast spiralni transporter za žito za mlinarje." },
    royal_sovereign_grainauger = { name = "Kraljevski suveren spiralni transporter za žito", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren spiralni transporter za žito z biseri za krono." },
}
local BUILDINGS = {
    grainauger_workshop = { name = "Grainauger delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    grainauger_house = { name = "Grainauger hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_grainauger_atelier = { name = "Mojstrski grainauger atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_grainauger_palace = { name = "Suverena grainauger palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GrainAugerMaker.ironStock=18; GrainAugerMaker.bronzeStock=14; GrainAugerMaker.woodStock=10; GrainAugerMaker.leatherStock=8; GrainAugerMaker.silverStock=8; GrainAugerMaker.goldStock=6; GrainAugerMaker.jewelStock=4; GrainAugerMaker.pearlStock=4
GrainAugerMaker.productStock = {}; GrainAugerMaker.buildings = {}; GrainAugerMaker.maker = nil; GrainAugerMaker.activeMaking = {}; GrainAugerMaker.totalProducts = 0; GrainAugerMaker.dayTimer = 0
function GrainAugerMaker.init() GrainAugerMaker.ironStock=18; GrainAugerMaker.bronzeStock=14; GrainAugerMaker.woodStock=10; GrainAugerMaker.leatherStock=8; GrainAugerMaker.silverStock=8; GrainAugerMaker.goldStock=6; GrainAugerMaker.jewelStock=4; GrainAugerMaker.pearlStock=4; GrainAugerMaker.productStock={}; GrainAugerMaker.buildings={}; GrainAugerMaker.maker=nil; GrainAugerMaker.activeMaking={}; GrainAugerMaker.totalProducts=0; GrainAugerMaker.dayTimer=0; print("[GrainAugerMaker] Royal Grain Auger Maker System initialized (6 products, 4 buildings)") end
function GrainAugerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainAugerMaker.maker={name=n or ("Spiralar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Spiralar najet: %s (spretnost: %d)",GrainAugerMaker.maker.name,s),"success") end; return true end
function GrainAugerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainAugerMaker.build(id) local ok,e=GrainAugerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainAugerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainAugerMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainAugerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainAugerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GrainAugerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GrainAugerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GrainAugerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GrainAugerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GrainAugerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainAugerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainAugerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainAugerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainAugerMaker.buildings==0 then return false,"Potrebna spiralna delavnica" end; if not GrainAugerMaker.maker then return false,"Potreben spiralar" end; return true end
function GrainAugerMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainAugerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GrainAugerMaker.ironStock=GrainAugerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GrainAugerMaker.bronzeStock=GrainAugerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GrainAugerMaker.woodStock=GrainAugerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GrainAugerMaker.leatherStock=GrainAugerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GrainAugerMaker.silverStock=GrainAugerMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainAugerMaker.goldStock=GrainAugerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainAugerMaker.jewelStock=GrainAugerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainAugerMaker.pearlStock=GrainAugerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainAugerMaker.maker then t=math.max(1,t-math.floor(GrainAugerMaker.maker.skill/13)) end; table.insert(GrainAugerMaker.activeMaking,{id="grainauger_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainAugerMaker.completeMaking(m) local q=1.0+(GrainAugerMaker.getQualityBonus()/100); if GrainAugerMaker.maker then q=q+(GrainAugerMaker.maker.skill/140) end; q=math.min(2.5,q); GrainAugerMaker.productStock[m.productType]=(GrainAugerMaker.productStock[m.productType] or 0)+m.quantity; GrainAugerMaker.totalProducts=GrainAugerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainAugerMaker.maker then GrainAugerMaker.maker.itemsMade=GrainAugerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainAugerMaker.maker.skill=math.min(100,GrainAugerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Spirala izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grainauger.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GrainAugerMaker.update(dt) if not _G.state then return end; GrainAugerMaker.dayTimer=GrainAugerMaker.dayTimer+dt; if GrainAugerMaker.dayTimer>=30 then GrainAugerMaker.dayTimer=0; for i=#GrainAugerMaker.activeMaking,1,-1 do local m=GrainAugerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainAugerMaker.completeMaking(m); table.remove(GrainAugerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainAugerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainAugerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainAugerMaker.getStats() return {ironStock=GrainAugerMaker.ironStock,bronzeStock=GrainAugerMaker.bronzeStock,woodStock=GrainAugerMaker.woodStock,leatherStock=GrainAugerMaker.leatherStock,silverStock=GrainAugerMaker.silverStock,goldStock=GrainAugerMaker.goldStock,jewelStock=GrainAugerMaker.jewelStock,pearlStock=GrainAugerMaker.pearlStock,productStock=GrainAugerMaker.productStock,numBuildings=#GrainAugerMaker.buildings,hasMaker=GrainAugerMaker.maker~=nil,makerName=GrainAugerMaker.maker and GrainAugerMaker.maker.name or "—",makerSkill=GrainAugerMaker.maker and GrainAugerMaker.maker.skill or 0,activeMaking=#GrainAugerMaker.activeMaking,totalProducts=GrainAugerMaker.totalProducts} end
return GrainAugerMaker
